$_MODULE['<{lggooglereviews}prestashop>help_b1e986d1a578a5ff89bedf9d5e52b012'] = 'Para utilizar las API de Google Maps y Places, debe registrar la aplicación y obtener una clave de API. Le explicamos cómo obtener esta clave si no sabe como hacerlo.';
